import { useEffect, useRef, useState } from "react";
import { createRoot, type Root } from "react-dom/client";
import { CheckIcon, CopyIcon } from "lucide-react";
import {
  Conversation,
  ConversationContent,
  ConversationEmptyState,
  ConversationScrollButton,
} from "./ai-elements/conversation";
import {
  Message,
  MessageAction,
  MessageActions,
  MessageContent,
  MessageResponse,
} from "./ai-elements/message";
import {
  PromptInput,
  PromptInputBody,
  PromptInputFooter,
  PromptInputSubmit,
  PromptInputTextarea,
  PromptInputTools,
} from "./ai-elements/prompt-input";
import "./ai-chat.css";

export interface AiChatMessage {
  id: string;
  role: "user" | "agent" | "system";
  content: string;
  hasCanvas: boolean;
}

export interface AiChatProps {
  messages: AiChatMessage[];
  draft: string;
  sending: boolean;
  ready: boolean;
  error: string | null;
  modelLabel: string;
  statusLabel: string;
  clearLabel: string;
  saveStatus: string | null;
  onDraftChange: (text: string) => void;
  onSend: (text: string) => void;
  onClear: () => void;
}

function AiChat(props: AiChatProps) {
  const [copied, setCopied] = useState<string | null>(null);
  const copyTimer = useRef<number | undefined>(undefined);
  const textareaRef = useRef<HTMLTextAreaElement | null>(null);

  useEffect(() => () => window.clearTimeout(copyTimer.current), []);

  async function copyMessage(id: string, text: string) {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(id);
      window.clearTimeout(copyTimer.current);
      copyTimer.current = window.setTimeout(() => setCopied(null), 2000);
    } catch {
      setCopied("failed");
    }
  }

  return (
    <section className="ai-chat-root flex h-full min-h-0 flex-col" aria-label="Conversation">
      <div className="flex min-h-9 items-center justify-between gap-2 px-3.5 py-2 text-[11px] text-muted-foreground">
        {props.modelLabel ? <span>{props.modelLabel}</span> : <span />}
        {props.messages.length > 0 && (
          <button
            type="button"
            className="rounded-md px-2 py-1 hover:bg-secondary hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring"
            disabled={props.sending}
            title="Clear the visible transcript. The server session is retained."
            onClick={() => {
              props.onClear();
              textareaRef.current?.focus();
            }}
          >
            {props.clearLabel}
          </button>
        )}
      </div>

      <Conversation className="min-h-0 flex-1">
        <ConversationContent>
          {props.messages.length === 0 && !props.sending ? (
            <ConversationEmptyState
              title="Start a conversation"
              description="Type a message below to begin chatting"
            />
          ) : (
            props.messages.map((message) => (
              <Message
                key={message.id}
                from={message.role === "agent" ? "assistant" : message.role}
              >
                <MessageContent>
                  <MessageResponse>{message.content}</MessageResponse>
                  {message.hasCanvas && (
                    <p className="text-[11px] text-muted-foreground">
                      Interface rendered on the canvas
                    </p>
                  )}
                </MessageContent>
                {message.role === "agent" && (
                  <MessageActions>
                    <MessageAction
                      label="Copy response"
                      onClick={() => void copyMessage(message.id, message.content)}
                    >
                      {copied === message.id ? (
                        <CheckIcon className="size-3" />
                      ) : (
                        <CopyIcon className="size-3" />
                      )}
                    </MessageAction>
                  </MessageActions>
                )}
              </Message>
            ))
          )}
          {props.sending && (
            <Message from="assistant">
              <MessageContent>
                <p aria-hidden="true">Thinking…</p>
              </MessageContent>
            </Message>
          )}
        </ConversationContent>
        <ConversationScrollButton />
      </Conversation>

      <footer className="shrink-0 border-t border-border p-3">
        {props.error && (
          <p role="alert" className="pb-2 text-xs text-destructive">
            {props.error}
          </p>
        )}
        <PromptInput
          onSubmit={(message) => {
            if (message.text.trim()) props.onSend(message.text);
          }}
        >
          <PromptInputBody>
            <PromptInputTextarea
              ref={textareaRef}
              id="svelte-chat-message"
              aria-label="Message"
              placeholder="Message"
              value={props.draft}
              disabled={!props.ready}
              onChange={(event) => props.onDraftChange(event.currentTarget.value)}
            />
          </PromptInputBody>
          <PromptInputFooter>
            <PromptInputTools>
              <span className="px-1 text-[10px] text-muted-foreground capitalize">
                {props.statusLabel}
              </span>
            </PromptInputTools>
            <PromptInputSubmit
              aria-label={props.sending ? "Sending" : "Send"}
              status={props.sending ? "streaming" : "ready"}
              disabled={!props.ready || !props.draft.trim() || props.sending}
            />
          </PromptInputFooter>
        </PromptInput>
        <p className="pt-2 text-center text-[9px] text-muted-foreground">
          Enter to send · Shift + Enter for a new line
        </p>
        <p className="sr-only" role="status" aria-live="polite">
          {props.sending
            ? "Waiting for a response."
            : (props.saveStatus ??
              (copied === "failed" ? "Could not copy the response." : "Ready."))}
        </p>
      </footer>
    </section>
  );
}

/** Mount the React AI Elements surface; the Svelte host owns this boundary. */
export function mountAiChat(container: HTMLElement, props: AiChatProps): Root {
  const root = createRoot(container);
  root.render(<AiChat {...props} />);
  return root;
}

export function updateAiChat(root: Root, props: AiChatProps): void {
  root.render(<AiChat {...props} />);
}

