  return {
    content: [reply.trim(), ...notes].filter(Boolean).join("\n\n"),
    ...(canvasSpecs.length ? { canvasSpec: canvasSpecs[0], scratch: true } : {}),
    ...(canvasSpecs.length > 1 ? { canvasSpecs } : {}),
    ...(registeredNames.length ? { registered: registeredNames } : {}),
  };
